"use client";

import { useEffect, useState } from "react";
import { Check, Star } from "lucide-react";

export default function PackagesPage() {
  const [packages, setPackages] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [billingCycle, setBillingCycle] = useState<"monthly" | "yearly">("monthly");

  useEffect(() => {
    fetch("/api/packages")
      .then(res => res.json())
      .then(data => {
        setPackages(data.packages || []);
        setLoading(false);
      })
      .catch(() => {
        setPackages([]);
        setLoading(false);
      });
  }, []);

  if (loading) return <p className="p-10">Loading...</p>;

  return (
    <div className="p-10 bg-white min-h-screen">
      {/* TOP HEADER */}
      <div className="flex flex-col items-center mb-10">
        <span className="text-sm text-green-600 font-medium flex items-center gap-2">
          ✓ 100% Money-back Guarantee
        </span>

        <h1 className="text-4xl font-bold mt-4">Our Pricing</h1>

        {/* Monthly / Yearly Toggle */}
        <div className="mt-5 flex items-center gap-2 bg-gray-100 px-2 py-1 rounded-full">
          <button
            className={`px-5 py-2 rounded-full text-sm font-semibold transition ${
              billingCycle === "monthly" ? "bg-black text-white" : "text-gray-600"
            }`}
            onClick={() => setBillingCycle("monthly")}
          >
            Monthly
          </button>

          <button
            className={`px-5 py-2 rounded-full text-sm font-semibold transition ${
              billingCycle === "yearly" ? "bg-black text-white" : "text-gray-600"
            }`}
            onClick={() => setBillingCycle("yearly")}
          >
            Yearly
          </button>
        </div>
      </div>

      {/* PRICING GRID */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6 max-w-7xl mx-auto">
        {packages.map((pkg) => {
          const monthly = Number(pkg.price);
          const yearly = Math.round(monthly * 12 * 0.7); // 30% discount like screenshot
          const price = billingCycle === "monthly" ? monthly : yearly;

          const isPopular = pkg.isPopular;

          return (
            <div
              key={pkg.id}
              className={`relative p-8 rounded-3xl border min-h-[700px] flex flex-col 
                ${isPopular ? "bg-black text-white border-black shadow-2xl scale-[1.02]" : "bg-white border-gray-200"}
              `}
            >
              {/* Popular Badge */}
              {isPopular && (
                <div className="absolute top-4 right-4 bg-white text-black px-3 py-1 text-xs rounded-full font-semibold flex items-center gap-1">
                  <Star size={14} className="text-yellow-500" />
                  Popular
                </div>
              )}

              {/* Plan Title */}
              <h2 className={`text-2xl font-bold mb-1`}>
                {pkg.name}
              </h2>

              {/* Price */}
              <div className="mt-2">
                <div className={`text-4xl font-bold`}>
                  ₹{price}
                  <span className="text-sm font-normal">
                    {billingCycle === "monthly" ? "/mo" : "/year"}
                  </span>
                </div>
              </div>

              {/* CTA */}
              <button
                className={`mt-5 w-full py-3 rounded-xl font-semibold transition ${
                  isPopular
                    ? "bg-white text-black hover:bg-gray-200"
                    : "bg-black text-white hover:bg-gray-800"
                }`}
              >
                {isPopular ? "Get started" : "Get Started"}
              </button>

              {/* Divider */}
              <div className="w-full h-px my-6 bg-gray-200 opacity-50"></div>

              {/* Feature Title */}
              <h3
                className={`text-sm font-bold tracking-wider mb-4 ${
                  isPopular ? "text-gray-300" : "text-gray-600"
                }`}
              >
                {pkg.isPopular ? "EVERYTHING IN UNLIMITED +" : "KEY FEATURES:"}
              </h3>

              {/* Features */}
              <ul className="space-y-3 flex-1 text-sm">
                {pkg.features.map((f: string, idx: number) => (
                  <li key={idx} className="flex items-start gap-3">
                    <Check
                      size={18}
                      className={`${isPopular ? "text-white" : "text-green-600"} mt-1`}
                    />
                    <span className={`${isPopular ? "text-gray-200" : "text-gray-700"}`}>
                      {f}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          );
        })}
      </div>
    </div>
  );
}